/// <summary>
/// PaffH 10.12.21
/// test logger class
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    NDXLoggerSecurityInformationClass loggerClass = NDXLoggerSecurityInformationClass::construct();
    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogTitle(strFmt("@NDXLogger:NDXLogTitleTest", 1));
    NDXLoggerSecurityInformationTable loggerTable = loggerClass.Start(argsLogger);

    argsLogger.parmLogActivity(strFmt("@NDXLogger:NDXLogActivityTest",1));
    loggerClass.LogLineCreate(argsLogger);
    argsLogger.parmCounter(10);
    loggerClass.LogLineChange(argsLogger);

    argsLogger.parmLogActivity(strFmt("@NDXLogger:NDXLogActivityTest",2));
    loggerClass.LogLineCreate(argsLogger);
    argsLogger.parmCounter(5);
    loggerClass.LogLineChange(argsLogger);

    loggerClass.DeleteLogTableRecord(loggerTable);
}
